interface Props {
  name: HomeIconName;
  /** 正方图标的边长;非正方字形请改用 width/height */
  size?: number;
  /** 覆盖宽度(缺省取 size) */
  width?: number;
  /** 覆盖高度(缺省取 size) */
  height?: number;
  color?: string;
  strokeWidth?: number;
}

export default function HomeIcon({
  name,
  size = 20,
  width,
  height,
  color = '#191A25',
  strokeWidth = 1.8,
}: Props) {
  const icon = ICONS[name];
  const viewBox = icon.viewBox ?? '0 0 24 24';
  const w = width ?? size;
  const h = height ?? size;
  if (icon.filled) {
    return (
      <Svg width={w} height={h} viewBox={viewBox}>
        <Path d={icon.d} fill={color} fillRule="evenodd" clipRule="evenodd" />
      </Svg>
    );
  }
  return (
    <Svg width={w} height={h} viewBox={viewBox}>
      <Path
        d={icon.d}
        stroke={color}
        strokeWidth={strokeWidth}
        strokeLinecap="round"
        strokeLinejoin="round"
        fill="none"
      />
    </Svg>
  );
}
